  ingress { from_port = 9042 to_port = 9042 protocol = "tcp" cidr_blocks = ["10.0.0.0/8"] }
  ingress { from_port = 9160 to_port = 9160 protocol = "tcp" cidr_blocks = ["10.0.0.0/8"] }
}
