```hcl
# Terraform: ensure no public IPv4 CIDR wider than /24
resource "aws_security_group" "<example_resource_name>" {
  name   = "<example_resource_name>"
  vpc_id = "<example_resource_id>"

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["203.0.113.0/24"] # Critical: /24 (or private RFC1918) avoids wide-open public /1-/23
  }
}
```

